                    "consumption_id": event.consumption_id,
                    "issuer_did": event.issuer_did,
                    "presentation_id": event.presentation_id,
                    "consumed_at": event.consumed_at,
                }
                for event in events
            ],
            "next_after": next_after,
        },
    )

